#include "WorkshopRuntime.hpp"
namespace elysium::industry {bool WorkshopRuntime::add(WorkshopState s,std::string&w){if(!s.id||!s.type){w="invalid workshop";return false;}s.condition=std::clamp(std::isfinite(s.condition)?s.condition:0.0,0.0,1.0);if(!rows_.emplace(s.id,s).second){w="duplicate workshop";return false;}return true;}void WorkshopRuntime::applyUse(StableId id,double wear,double c,double e){auto i=rows_.find(id);if(i==rows_.end())return;auto&x=i->second;++x.cycles;x.contamination=std::max(0.0,c);x.environmentStress=std::max(0.0,e);x.condition=std::clamp(x.condition-std::max(0.0,wear)-x.contamination*.01-x.environmentStress*.01,0.0,1.0);}std::optional<MaintenanceRequest>WorkshopRuntime::maintenanceNeed(StableId id,double preventive,double failure)const{auto i=rows_.find(id);if(i==rows_.end())return std::nullopt;double urgency=1.0-i->second.condition;if(urgency<preventive)return std::nullopt;return MaintenanceRequest{id,std::clamp(urgency,0.0,1.0),urgency>=failure?2ULL:1ULL};}bool WorkshopRuntime::repair(StableId id,double r,std::string&w){auto i=rows_.find(id);if(i==rows_.end()){w="unknown workshop";return false;}if(r<=0){w="no consumed repair work";return false;}i->second.condition=std::clamp(i->second.condition+r,0.0,1.0);return true;}}
